$('story-form').addEventListener('submit',async event=>{event.preventDefault();const sourceResult=readSources(),exploreResult=readExplore();if(sourceResult.error||exploreResult.error){message(sourceResult.error||exploreResult.error);return}const story={slug:$('slug').value.trim(),status:$('story-status').value,classification:$('classification').value,place:{city:$('city').value.trim(),region:$('region').value.trim(),country:$('country').value.trim(),latitude:Number($('latitude').value),longitude:Number($('longitude').value),precision:$('precision-exact').checked?'exact':'approximate',...($('street-view-url').value.trim()?{streetViewUrl:$('street-view-url').value.trim()}:{}),...($('map-query').value.trim()?{mapQuery:$('map-query').value.trim()}:{})},eventDate:$('event-date').value.trim()||null,publishedAt:$('published-at').value,updatedAt:$('updated-at').value,sources:sourceResult.sources,explore:exploreResult.explore,translations:Object.fromEntries(['pt','en','es'].map(lang=>[lang,Object.fromEntries(['title','summary','body'].map(key=>[key,$(lang+'-'+key).value.trim()]))]))};const dashes=['pt','en','es'].flatMap(lang=>['title','summary','body'].map(key=>(story.translations[lang][key].match(/[—–]/g)||[]).length)).reduce((a,b)=>a+b,0);if(dashes){for(const lang of ['pt','en','es'])for(const key of ['title','summary','body'])$(lang+'-'+key).value=removeDashes($(lang+'-'+key).value);message(`${dashes} travessão(ões) (— ou –) foram trocados por vírgulas, parênteses ou hífen. Revise o texto nas abas de idioma e clique em Salvar novamente.`);$('form-status').scrollIntoView({behavior:'smooth',block:'center'});return}const isNew=!$('slug').readOnly;try{await api('/api/admin/stories',{method:'POST',body:JSON.stringify(story)});if(isNew)storyPage=0;$('story-form').hidden=true;message(story.status==='published'?'História salva e publicada. No site, pode levar até 5 minutos para aparecer.':'História salva. Ela só aparece no site quando a situação for “Publicada”.');await refresh();$('status').scrollIntoView({behavior:'smooth',block:'center'})}catch(error){message(error.message);$('form-status').scrollIntoView({behavior:'smooth',block:'center'})}});

$('street-view-preview').addEventListener('click',event=>{const point=editorCoordinates();if(!point){event.preventDefault();message('Informe latitude e longitude válidas para conferir no Street View.');return}event.currentTarget.href=`https://www.google.com/maps/search/?api=1&query=${point[0]},${point[1]}`});

// Abas do formulário: configurações e um texto por idioma.
const formTabs=[['settings','Configurações'],['pt','Português'],['en','English'],['es','Español']];
const tabBar=document.createElement('div');tabBar.className='admin-tabs';tabBar.setAttribute('role','tablist');
const settingsPanel=document.createElement('div');settingsPanel.id='tab-settings';
while($('form-title').nextElementSibling!==$('translations'))settingsPanel.append($('form-title').nextElementSibling);
$('form-title').after(tabBar,settingsPanel);
const tabPanels={settings:settingsPanel};
for(const section of $('translations').querySelectorAll('.admin-translations')){const lang=section.querySelector('input').id.split('-')[0];section.id='tab-'+lang;section.querySelector('h3').remove();tabPanels[lang]=section}
for(const [key,label] of formTabs){const tab=makeButton(label,()=>showTab(key));tab.id='tab-button-'+key;tab.setAttribute('role','tab');tab.setAttribute('aria-controls','tab-'+key);tabPanels[key].setAttribute('role','tabpanel');tabPanels[key].setAttribute('aria-labelledby',tab.id);tabBar.append(tab)}
tabBar.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;const keys=formTabs.map(([key])=>key),current=keys.findIndex(key=>!tabPanels[key].hidden);const next=keys[(current+(event.key==='ArrowRight'?1:keys.length-1))%keys.length];showTab(next);$('tab-button-'+next).focus()});
function showTab(key){for(const [name] of formTabs){const selected=name===key;tabPanels[name].hidden=!selected;const tab=$('tab-button-'+name);tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1}if(key==='settings'&&editorMap&&!$('admin-map').hidden)setTimeout(()=>editorMap.invalidateSize())}
// Campo obrigatório vazio em outra aba: abre a aba para o navegador mostrar o aviso.
$('story-form').addEventListener('invalid',event=>{const panel=Object.entries(tabPanels).find(([,element])=>element.contains(event.target));if(panel&&panel[1].hidden){showTab(panel[0]);message(`Preencha os campos obrigatórios da aba ${formTabs.find(([key])=>key===panel[0])[1]}.`)}},true);
showTab('settings');
// Exclusão definitiva: pede o identificador digitado para evitar cliques acidentais.
$('delete-story').addEventListener('click',async()=>{const slug=$('slug').value.trim();const title=$('pt-title').value.trim()||slug;
 const typed=prompt(`Excluir definitivamente “${title}”?\n\nA história sai do site e do painel, junto com todos os comentários dela. Esta ação não pode ser desfeita.\n\nPara confirmar, digite o identificador: ${slug}`);
 if(typed===null)return;if(typed.trim()!==slug){message('Exclusão cancelada: o identificador digitado não confere.');return}
 try{await api(`/api/admin/stories?slug=${encodeURIComponent(slug)}`,{method:'DELETE'});$('story-form').hidden=true;message(`História “${title}” excluída. No site, pode levar até 5 minutos para sumir.`);await refresh();$('status').scrollIntoView({behavior:'smooth',block:'center'})}
 catch(error){message(error.message);$('form-status').scrollIntoView({behavior:'smooth',block:'center'})}});
// Revisão de texto publicada pelo desenvolvedor em text-fixes.json: mostra as correções ainda pendentes
// (trechos que ainda existem nas histórias) e as aplica pelo mesmo endpoint de salvamento.
let textFixes=null;
fetch('/admin/text-fixes.json',{cache:'no-store'}).then(response=>response.ok?response.json():null).then(data=>{textFixes=data;renderTextFixes()}).catch(()=>{});
function applyPendingTextFixes(story){for(const fix of pendingTextFixes().filter(fix=>fix.slug===story.slug)){const current=story.translations[fix.lang][fix.field];story.translations[fix.lang][fix.field]=fix.all?current.split(fix.from).join(fix.to):current.replace(fix.from,fix.to)}return story}
function pendingTextFixes(){if(!textFixes?.fixes)return [];return textFixes.fixes.filter(fix=>{const text=storyItems.find(story=>story.slug===fix.slug)?.translations?.[fix.lang]?.[fix.field];return typeof text==='string'&&(fix.all?text.includes(fix.from):text.split(fix.from).length===2)})}
function renderTextFixes(){const panel=$('text-fixes');const pending=pendingTextFixes();panel.replaceChildren();panel.hidden=!pending.length;if(!pending.length)return;
 const stories=new Set(pending.map(fix=>fix.slug));const heading=document.createElement('h2');heading.textContent='Revisão de texto pendente';const text=document.createElement('p');text.textContent=`${textFixes.description} ${pending.length} correções em ${stories.size} histórias. Antes de aplicar, baixe a cópia de segurança.`;
 const list=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Ver as correções';list.append(summary);for(const fix of pending){const item=document.createElement('p');item.className='admin-fix';const title=document.createElement('strong');title.textContent=`${fix.slug} · ${fix.lang.toUpperCase()}`;const before=document.createElement('del');before.textContent=fix.from;const after=document.createElement('ins');after.textContent=fix.to;item.append(title,before,after);list.append(item)}
 const actions=document.createElement('div');actions.className='admin-actions';
 const backup=makeButton('Baixar cópia de segurança',()=>{const blob=new Blob([JSON.stringify(storyItems,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`nocturna-historias-${new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);apply.disabled=false});
 const apply=makeButton(`Aplicar ${pending.length} correções`,async()=>{if(!confirm(`Aplicar ${pending.length} correções de texto em ${stories.size} histórias?`))return;apply.disabled=backup.disabled=true;let done=0;const failed=[];
  for(const slug of stories){const story=structuredClone(storyItems.find(item=>item.slug===slug));for(const fix of pending.filter(fix=>fix.slug===slug)){const current=story.translations[fix.lang][fix.field];if(fix.all)story.translations[fix.lang][fix.field]=current.split(fix.from).join(fix.to);else if(current.split(fix.from).length===2)story.translations[fix.lang][fix.field]=current.replace(fix.from,fix.to)}
   try{await api('/api/admin/stories',{method:'POST',body:JSON.stringify(story)});done++;message(`Aplicando correções: ${done} de ${stories.size} histórias…`)}catch(error){failed.push(`${slug}: ${error.message}`)}}
  message(failed.length?`Correções aplicadas em ${done} histórias. Falharam: ${failed.join('; ')}`:`Correções aplicadas em ${done} histórias. No site, pode levar até 5 minutos para aparecer.`);await refresh()});
 apply.className='primary';apply.disabled=true;actions.append(backup,apply);panel.append(heading,text,list,actions)}
// Sugestões de local exato (place-suggestions.json): cada uma pode ser desmarcada antes de aplicar.
let placeSuggestions=null;
const dismissedSuggestions=()=>{try{return JSON.parse(localStorage.getItem('nocturna-dismissed-places')||'[]')}catch{return []}};
fetch('/admin/place-suggestions.json',{cache:'no-store'}).then(response=>response.ok?response.json():null).then(data=>{placeSuggestions=data;renderPlaceSuggestions()}).catch(()=>{});
function renderPlaceSuggestions(){const panel=$('place-suggestions');panel.replaceChildren();
 const pending=(placeSuggestions?.suggestions||[]).map(item=>({...item,story:storyItems.find(story=>story.slug===item.slug)})).filter(item=>item.story&&item.story.place?.precision!=='exact'&&!dismissedSuggestions().includes(item.slug));
 panel.hidden=!pending.length;if(!pending.length)return;
 const heading=document.createElement('h2');heading.textContent='Sugestões de localização exata';const text=document.createElement('p');text.textContent=`${placeSuggestions.description} Desmarque o que não quiser alterar.`;
 const list=document.createElement('div');list.className='admin-suggestions';
 for(const item of pending){const label=document.createElement('label');label.className='admin-check';const box=document.createElement('input');box.type='checkbox';box.checked=true;box.value=item.slug;const title=document.createElement('span');title.textContent=`${item.story.translations?.pt?.title||item.slug} → ${item.mapQuery||'coordenadas cadastradas'} (${item.reason})`;label.append(box,title);list.append(label)}
 const actions=document.createElement('div');actions.className='admin-actions';
 const apply=makeButton('Aplicar selecionadas',async()=>{const chosen=pending.filter(item=>list.querySelector(`input[value="${item.slug}"]`).checked);if(!chosen.length){message('Nenhuma sugestão selecionada.');return}
  if(!confirm(`Marcar ${chosen.length} histórias como local exato?`))return;apply.disabled=true;try{localStorage.setItem('nocturna-dismissed-places',JSON.stringify([...dismissedSuggestions(),...pending.filter(item=>!chosen.includes(item)).map(item=>item.slug)]))}catch{}let done=0;const failed=[];
  for(const item of chosen){const story=applyPendingTextFixes(structuredClone(item.story));story.place={...story.place,precision:'exact',...(item.mapQuery?{mapQuery:item.mapQuery}:{})};try{await api('/api/admin/stories',{method:'POST',body:JSON.stringify(story)});done++;message(`Atualizando locais: ${done} de ${chosen.length}…`)}catch(error){failed.push(`${item.slug}: ${error.message}`)}}
  message(failed.length?`Locais atualizados em ${done} histórias. Falharam: ${failed.join('; ')}`:`Locais atualizados em ${done} histórias. No site, pode levar até 5 minutos para aparecer.`);await refresh()});
 apply.className='primary';actions.append(apply);panel.append(heading,text,list,actions)}
// Troca automática de travessões para o editor revisar (GUIA-EDITORIAL.md):
// "a — b — c" vira "a (b) c"; travessão isolado vira vírgula; meia-risca vira hífen (ou vírgula quando cercada de espaços).
function removeDashes(text){return text
 .replace(/(\S)–(\S)/g,'$1-$2')
 .replace(/[ \t]+–[ \t]+/g,', ')
 .replace(/[ \t]*—[ \t]*([^—\n]+?)[ \t]*—([ \t]*)/g,(match,inner,space)=>` (${inner.trim()})${space}`)
 .replace(/[ \t]*[—–][ \t]*/g,', ')
 .replace(/ \(([^)]*)\) ([,.;:!?])/g,' ($1)$2')
 .replace(/, ([,.;:!?])/g,'$1')
 .replace(/^(#{1,6} .*?), (e|and|y) /gm,'$1 $2 ')}
authenticated();
